WITH deduped AS (SELECT id, store_name, region, sqft FROM stores QUALIFY ROW_NUMBER() OVER (PARTITION BY city ORDER BY sqft, id) = 1) SELECT CASE WHEN sqft >= 16941 THEN 'PREMIUM' ELSE 'STANDARD' END AS sqft_tier, BIT_AND(sqft) AS sqft_bit_and, COUNT_IF(region = 'North') AS north_events, COUNT_IF(region = 'Central') AS central_events FROM deduped GROUP BY CASE WHEN sqft >= 16941 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING BIT_AND(sqft) < 1000 ORDER BY sqft_bit_and DESC NULLS FIRST
